What does this print?

```ts
class Bag {
  items: string[] = []
  add(x: string) { this.items.push(x) }
  addAll(xs: string[]) { xs.forEach((x) => this.add(x)) }
}
class CountingBag extends Bag {
  count = 0
  add(x: string) { this.count++; super.add(x) }
  addAll(xs: string[]) { this.count += xs.length; super.addAll(xs) }
}
const b = new CountingBag()
b.addAll(['a', 'b'])
console.log(b.count)
```

